{"command": "cat > /workspace/build_patterns.py << 'PYEOF'
import json

# Pattern cells: (pattern, row, channel, note, instrument, volume, effect, effect_param)
# Channels: 0=Kick, 1=Snare, 2=HiHat, 3=Bass, 4=Lead, 5=Pad, 6=FX, 7=Empty

# Key: A minor (A, B, C, D, E, F, G)
# Notes in tracker format: C-3 = 60, C#3 = 61, D-3 = 62, etc.
# C-4 = 64 (middle C), A-3 = 57

def make_cell(p, r, ch, note=None, inst=None, vol=None, eff=None, effp=None):
    cell = {"pattern": p, "row": r, "channel": ch}
    if note is not None:
        cell["note"] = note
    if inst is not None:
        cell["instrument"] = inst
    if vol is not None:
        cell["volume"] = vol
    if eff is not None:
        cell["effect"] = eff
    if effp is not None:
        cell["effect_param"] = effp
    return cell

patterns = []

# Pattern 0: Intro (kick + hat)
for row in range(0, 64, 4):  # Every 4 rows (1 bar)
    patterns.append(make_cell(0, row, 0, "C-3", 1))  # Kick
    patterns.append(make_cell(0, row + 2, 2, "C-3", 3))  # HiHat

# Pattern 1: Add snare
for row in range(64):
    if row % 4 == 0:
        patterns.append(make_cell(1, row, 0, "C-3", 1))  # Kick
    if row % 16 == 8:
        patterns.append(make_cell(1, row, 1, "C-3", 2))  # Snare

# Pattern 2: Add bass (A2 = A-3 = 57)
for row in range(0, 64, 1):
    if row % 2 == 0:
        patterns.append(make_cell(2, row, 3, "A-3", 4))  # Bass

# Pattern 3: Lead starts
for row in range(64):
    if row % 8 < 4:
        patterns.append(make_cell(3, row, 4, "A-4", 5))  # Lead A4
    elif row % 8 == 4:
        patterns.append(make_cell(3, row, 4, "C-4", 5))  # Lead C4
    else:
        patterns.append(make_cell(3, row, 4, "D-4", 5))  # Lead D4

# Pattern 4: Full beat + bass
for row in range(64):
    if row % 4 == 0:
        patterns.append(make_cell(4, row, 0, "C-3", 1))  # Kick
    if row % 16 == 8:
        patterns.append(make_cell(4, row, 1, "C-3", 2))  # Snare
    if row % 2 == 0:
        patterns.append(make_cell(4, row, 3, "A-3", 4))  # Bass
    if row % 4 < 2:
        patterns.append(make_cell(4, row, 2, "C-3", 3))  # HiHat

# Pattern 5: Lead melody (A minor arpeggio)
for row in range(64):
    if row % 8 == 0:
        patterns.append(make_cell(5, row, 4, "A-4", 5, 64))  # A4
    elif row % 8 == 1:
        patterns.append(make_cell(5, row, 4, "C-4", 5, 64))  # C4
    elif row % 8 == 2:
        patterns.append(make_cell(5, row, 4, "E-4", 5, 64))  # E4
    elif row % 8 == 3:
        patterns.append(make_cell(5, row, 4, "G-4", 5, 64))  # G4

# Pattern 6: Same as 4 with more hats
for row in range(64):
    if row % 4 == 0:
        patterns.append(make_cell(6, row, 0, "C-3", 1))  # Kick
    if row % 16 == 8:
        patterns.append(make_cell(6, row, 1, "C-3", 2))  # Snare
    if row % 2 == 0:
        patterns.append(make_cell(6, row, 3, "A-3", 4))  # Bass
    patterns.append(make_cell(6, row, 2, "C-3", 3))  # HiHat every beat

# Pattern 7: Breakdown (just bass and pad)
for row in range(0, 64, 4):
    patterns.append(make_cell(7, row, 3, "A-3", 4))  # Bass
    patterns.append(make_cell(7, row, 5, "A-3", 6))  # Pad

# Pattern 8: Breakdown continue
for row in range(0, 64, 2):
    patterns.append(make_cell(8, row, 3, "E-3", 4))  # Bass E3
    patterns.append(make_cell(8, row, 5, "C-4", 6))  # Pad C4

# Pattern 9: Buildup (ramping up)
for row in range(64):
    if row % 4 == 0:
        patterns.append(make_cell(9, row, 0, "C-3", 1))  # Kick
    if row % 8 == 0:
        patterns.append(make_cell(9, row, 2, "C-3", 3))  # HiHat
    if row % 4 == 2:
        patterns.append(make_cell(9, row, 3, "A-3", 4))  # Bass

# Pattern 10: More buildup
for row in range(64):
    if row % 4 == 0:
        patterns.append(make_cell(10, row, 0, "C-3", 1))  # Kick
    if row % 4 == 1:
        patterns.append(make_cell(10, row, 2, "C-3", 3))  # HiHat on offbeat

# Pattern 11: Drop
for row in range(64):
    if row % 4 == 0:
        patterns.append(make_cell(11, row, 0, "C-3", 1))
    if row % 16 == 8:
        patterns.append(make_cell(11, row, 1, "C-3", 2))
    if row % 2 == 0:
        patterns.append(make_cell(11, row, 3, "A-3", 4))
    if row % 8 < 4:
        patterns.append(make_cell(11, row, 4, "A-4", 5))
    if row % 8 < 2:
        patterns.append(make_cell(11, row, 2, "C-3", 3))

# Pattern 12: Drop continued
for row in range(64):
    if row % 4 == 0:
        patterns.append(make_cell(12, row, 0, "C-3", 1))
    if row % 16 == 8:
        patterns.append(make_cell(12, row, 1, "C-3", 2))
    if row % 2 == 0:
        patterns.append(make_cell(12, row, 3, "A-3", 4))
    patterns.append(make_cell(12, row, 4, "A-4", 5))
    if row % 4 < 2:
        patterns.append(make_cell(12, row, 2, "C-3", 3))

# Pattern 13: Variation
for row in range(64):
    if row % 4 == 0:
        patterns.append(make_cell(13, row, 0, "C-3", 1))
    if row % 16 == 8:
        patterns.append(make_cell(13, row, 1, "C-3", 2))
    if row % 2 == 0:
        patterns.append(make_cell(13, row, 3, "E-3", 4))
    if row % 4 < 2:
        patterns.append(make_cell(13, row, 4, "G-4", 5))
    if row % 4 < 2:
        patterns.append(make_cell(13, row, 2, "C-3", 3))

# Pattern 14: Build again
for row in range(64):
    if row % 8 == 0:
        patterns.append(make_cell(14, row, 0, "C-3", 1))
    if row % 4 == 2:
        patterns.append(make_cell(14, row, 3, "A-3", 4))

# Pattern 15: Final beat
for row in range(64):
    if row % 4 == 0:
        patterns.append(make_cell(15, row, 0, "C-3", 1))
    if row % 16 == 8:
        patterns.append(make_cell(15, row, 1, "C-3", 2))
    if row % 2 == 0:
        patterns.append(make_cell(15, row, 3, "A-3", 4))

# Save pattern data as JSON for batch processing
with open('/workspace/patterns.json', 'w') as f:
    json.dump(patterns, f)
print(f"Generated {len(patterns)} pattern cells")
PYEOF
python3 /workspace/build_patterns.py"}

