import json

# Pattern cells: (pattern, row, channel, note, instrument, volume, effect, effect_param)
# Channels: 0=Kick, 1=Snare, 2=HiHat, 3=Bass, 4=Lead, 5=Pad, 6=FX, 7=Empty

# Key: A minor (A, B, C, D, E, F, G)
# Notes in tracker format: C-3 = 60, C#3 = 61, D-3 = 62, etc.
# C-4 = 64 (middle C), A-3 = 57

def make_cell(p, r, ch, note=None, inst=None, vol=None, eff=None, effp=None):
    cell = {"pattern": p, "row": r, "channel": ch}
    if note is not None:
        cell["note"] = note
    if inst is not None:
        cell["instrument"] = inst
    if vol is not None:
        cell["volume"] = vol
    if eff is not None:
        cell["effect"] = eff
    if effp is not None:
        cell["effect_param"] = effp
    return cell

patterns = []

# Pattern 0: Intro (kick + hat)
for row in range(0, 64, 4):  # Every 4 rows (1 bar)
    patterns.append(make_cell(0, row, 0, "C-3", 1))  # Kick
    patterns.append(make_cell(0, row + 2, 2, "C-3", 3))  # HiHat

# Pattern 1: Add snare
for row in range(64):
    if row % 4 == 0:
        patterns.append(make_cell(1, row, 0, "C-3", 1))  # Kick
    if row % 16 == 8:
        patterns.append(make_cell(1, row, 1, "C-3", 2))  # Snare

# Pattern 2: Add bass (A2 = A-3 = 57)
for row in range(0, 64, 1):
    if row % 2 == 0:
        patterns.append(make_cell(2, row, 3, "A-3", 4))  # Bass

# Pattern 3: Lead starts
