        patterns.append(make_cell(3, row, 4, "A-4", 5))  # Lead A4
    elif row % 8 == 4:
        patterns.append(make_cell(3, row, 4, "C-4", 5))  # Lead C4
    else:
        patterns.append(make_cell(3, row, 4, "D-4", 5))  # Lead D4

# Pattern 4: Full beat + bass
for row in range(64):
